import { pxToRem } from "../../helpers";
import { StyleFn } from "..";

/**
 * List classes used in PopoverMenu, SideNav, ComboBox, etc.
 **/
export const List: StyleFn = (theme, mode) => {
  const { color, font, size, opacity } = theme;
  const hoverBGColor = color.surface.interaction.hover[mode];
  const activeBGColor = color.surface.interaction.active[mode];
  const focusStyles = {
    outline: "none",
    boxShadow: `inset 0px 0px 0px 3px ${color.border.accent.focus[mode]}`,
  };

  return {
    root: {
      display: "block",
      listStyle: "none",
      minWidth: pxToRem(200),
      margin: 0,
      padding: `${size.spacing[4]} 0`,
      fontSize: font.size.small,
      lineHeight: font.lineheight.small,
      color: color.text.neutral.default[mode],
    },
    item: {
      display: "flex",
      flexWrap: "wrap",
      alignItems: "center",
      cursor: "pointer",
      padding: `${size.spacing[12]} ${size.spacing[12]}`,
      "&:hover, &:active, &[aria-selected=true]": {
        backgroundColor: hoverBGColor,
      },
      "&:focus-visible": focusStyles,
    },
    item_selected: {
      fontWeight: font.weight.bold,
      backgroundColor: activeBGColor,
    },
    item_disabled: {
      opacity: opacity.disabled,
      userSelect: "none",
      pointerEvents: "none",
    },
    item_quiet: {
      // increase specificity for dark theme
      "$item_quiet&": {
        "&$item_selected": {
          background: "unset",
          backgroundColor: "unset",
        },
        "&:hover": { backgroundColor: hoverBGColor },
        "&:active": { backgroundColor: activeBGColor },
        // "&[aria-selected=true]": {
        //   backgroundColor: activeBGColor,
        // },
      },
    },
    itemText: {
      flex: "1 1 auto",
    },
    itemIcon: {
        flexShrink: 0,
        marginRight: size.spacing[8],
        lineHeight: 1,
        "& i, & svg": {
          fontSize: font.size.medium,
          verticalAlign: "middle",
          color: color.text.accent.corporate[mode],
          fill: color.text.accent.corporate[mode],
          width: size.spacing[16],
          height: size.spacing[16],
        },
    },
  };
};

/** RETRO COMPATIBILITY with "ds-menu-*" classes */
export const Menu = List;
